def build_idioms_phrases_bank() -> list[GeneratedQuestion]:
    bank = [
        GeneratedQuestion(
            pattern_type=item["pattern_type"],
            subtopic=item["subtopic"],
            difficulty=item["difficulty"],
            expected_time_seconds=item["expected_time_seconds"],
            question_text=item["question_text"],
            options=tuple(item["options"]),  # type: ignore[arg-type]
            correct_option=item["correct_option"],
            explanation=item["explanation"],
            fast_method=item["fast_method"],
        )
        for item in _DATA
    ]
    if len(bank) != 100:
        raise AssertionError(f"Expected 100 questions, got {len(bank)}")
    return bank
